// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: the admin (deployer/msg.sender of setUp) may set
        // owner to ANY address, including zero and this contract's address.
        // No narrowing needed — the whole address space is admissible.

        vm.prank(admin());
        bool returned;
        try c.setOwner(newOwner) returns (bool r) {
            returned = r;
        } catch {
            returned = false;
        }

        // The return value must truthfully report the effect:
        // owner must now equal newOwner AND the call must report exactly that.
        assertTrue(returned && c.owner() == newOwner);
    }

    // helper to keep prank target explicit
    function admin() internal view returns (address) {
        return address(this);
    }
}
